const ORDER = ['tr', 'en', 'de', 'fr', 'nl', 'da', 'es', 'it'];
export function t(key, lang) {
  const row = key.includes('.') ? key.split('.').reduce((o, k) => o?.[k], T) : T[key];
  if (!row) return key;
  const i = ORDER.indexOf(lang);
  return row[i >= 0 ? i : 1] ?? row[1];
}

